/*----------------------------------------------------------------------------
| Types used to pass 16-bit, 32-bit, 64-bit, and 128-bit floating-point
| arguments and results to/from functions.  These types must be exactly
| 16 bits, 32 bits, 64 bits, and 128 bits in size, respectively.
*----------------------------------------------------------------------------*/
struct f16_t {
    uint16_t v;
#ifdef __cplusplus
    f16_t(uint16_t v16): v(v16) {}
    operator uint16_t() const { return v; }
#endif
};

struct f32_t {
    union {
      uint32_t v;
      float f;
    } u;
#ifdef __cplusplus
    f32_t(uint32_t v32) { u.v = v32; }
    f32_t(float f32) { u.f = f32; }
    operator uint32_t() const { return u.v; }
    operator float() const { return u.f; }
#endif
};

struct f64_t {
    union {
      uint64_t v;
      double f;
    } u;
#ifdef __cplusplus
    f64_t(uint64_t v64) { u.v = v64; }
    f64_t(double f64) { u.f = f64; }
    operator uint64_t() const { return u.v; }
    operator double() const { return u.f; }
#endif
};

